 # 3 times, to get into the whitelist:
-sarun ("-L -a -t < data/nice/002", \&patterns_run_cb);
-sarun ("-L -a -t < data/nice/002", \&patterns_run_cb);
-sarun ("-L -a -t < data/nice/002", \&patterns_run_cb);
+ok (sarun ("-L -a -t < data/nice/002", \&patterns_run_cb));
+ok (sarun ("-L -a -t < data/nice/002", \&patterns_run_cb));
+ok (sarun ("-L -a -t < data/nice/002", \&patterns_run_cb));

 # Now check
 ok (sarun ("-L -a -t < data/nice/002", \&patterns_run_cb));
 ok_all_patterns();

